style.css:
/* ================================
   DRAGON BALL SUPER – UNIVERSAL UI
   Inspired Anime Energy Theme
   ================================ */

:root {
  --dbs-bg: #0b0f1a;
  --dbs-bg-soft: #12182b;
  --dbs-text: #e8ecff;
  --dbs-blue: #3da9ff;
  --dbs-gold: #f5c542;
  --dbs-red: #ff4d4d;
  --dbs-glow-blue: 0 0 10px rgba(61, 169, 255, 0.8);
  --dbs-glow-gold: 0 0 10px rgba(245, 197, 66, 0.8);
}

/* Base */
html, body {
  background-color: var(--dbs-bg) !important;
  color: var(--dbs-text) !important;
  font-family: "Segoe UI", "Roboto", "Arial", sans-serif !important;
}

/* Containers */
div, section, main, article, aside, nav {
  background-color: var(--dbs-bg-soft) !important;
  color: var(--dbs-text) !important;
}

/* Links */
a {
  color: var(--dbs-blue) !important;
  text-shadow: var(--dbs-glow-blue);
}

a:hover {
  color: var(--dbs-gold) !important;
  text-shadow: var(--dbs-glow-gold);
}

/* Buttons */
button, input[type="submit"], input[type="button"] {
  background: linear-gradient(
    135deg,
    var(--dbs-blue),
    var(--dbs-gold)
  ) !important;
  color: #000 !important;
  border: none !important;
  border-radius: 8px !important;
  padding: 6px 12px !important;
  font-weight: bold !important;
  box-shadow: var(--dbs-glow-blue);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

button:hover {
  transform: scale(1.05);
  box-shadow: var(--dbs-glow-gold);
}

/* Inputs */
input, textarea, select {
  background-color: #0f1530 !important;
  color: var(--dbs-text) !important;
  border: 1px solid var(--dbs-blue) !important;
  border-radius: 6px !important;
}

/* Headers */
h1, h2, h3 {
  color: var(--dbs-gold) !important;
  text-shadow: var(--dbs-glow-gold);
}

h4, h5, h6 {
  color: var(--dbs-blue) !important;
  text-shadow: var(--dbs-glow-blue);
}

/* Cards / Panels */
[class*="card"], [class*="panel"], [class*="box"] {
  background-color: #10163a !important;
  border: 1px solid rgba(61, 169, 255, 0.4) !important;
  border-radius: 10px !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: #050814;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    var(--dbs-blue),
    var(--dbs-gold)
  );
  border-radius: 10px;
}

/* Selection */
::selection {
  background: var(--dbs-gold);
  color: #000;
}

/* Images – subtle energy aura */
img:hover {
  filter: drop-shadow(0 0 6px rgba(61,169,255,0.6));
}

/* Tables */
table {
  background-color: #0e1433 !important;
}

th {
  color: var(--dbs-gold) !important;
}

td {
  color: var(--dbs-text) !important;
}
